from itertools import permutations

langs = {
    "Korea": {"Korean"},
    "France": {"French", "German"},
    "Britain": {"English", "Korean"},
    "Germany": {"Korean", "French", "English", "German"},
}
# own language: Korean->Korean, France->French, Britain->English, Germany->German
own = {"Korea": "Korean", "France": "French", "Britain": "English", "Germany": "German"}

def comm(a, b):
    # can communicate if one speaks the other's native language
    return own[b] in langs[a] or own[a] in langs[b]

def valid(order):
    pos = {n: i for i, n in enumerate(order)}
    def nbrs(n):
        i = pos[n]
        return [order[j] for j in (i - 1, i + 1) if 0 <= j < 4]
    if not pos["Korea"] > pos["Germany"]:
        return False
    # Korean: can't communicate with any neighbor
    if any(comm("Korea", x) for x in nbrs("Korea")):
        return False
    # French: can't communicate with any neighbor
    if any(comm("France", x) for x in nbrs("France")):
        return False
    # British: communicates with exactly one neighbor
    if sum(comm("Britain", x) for x in nbrs("Britain")) != 1:
        return False
    return True

sols = [p for p in permutations(["Korea", "France", "Britain", "Germany"]) if valid(p)]
print("All valid orders:", sols)

options = {
    "A": ("Britain", "Germany", "Korea", "France"),
    "B": ("France", "Britain", "Germany", "Korea"),
    "C": ("Germany", "Britain", "France", "Korea"),
    "D": ("Germany", "Britain", "Korea", "France"),
}
for k, v in options.items():
    print(k, v, "valid" if valid(v) else "invalid")

submitted = "D"
if valid(options[submitted]) and len(sols) == 1:
    print("CHECK PASS")
else:
    print("CHECK FAIL: submitted option", submitted, "is not the valid arrangement;",
          "correct option(s):", [k for k, v in options.items() if valid(v)])
